/// <summary>
/// Display MGK/HK2 price (HK1 * HK2Factor * MGKFactor)
/// </summary>
/// <returns>MGK/HK2 Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display NDXHK2MGKPrice dispHK2MGKcurrent()
{
    AVAMGKFactors factor = AVAMGKFactors::findByRecId(this.NDXMGKGroupRefRecId);

    //security check  in NDX_showHK2current
    return this.dispHK2current() * (factor.MGKFactor ? factor.MGKFactor : 1);
}

/// <summary>
/// Display MGK Price (HK1 * MGKFactor)
/// </summary>
/// <returns>MGK Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display Price dispMGKcurrent()
{
    AVAMGKFactors factor = AVAMGKFactors::findByRecId(this.NDXMGKGroupRefRecId);

    //security check  in NDX_showHK1current
    return this.dispHK1current() * (factor.MGKFactor ? factor.MGKFactor : 1);
}

/// <summary>
/// get get active PriceDiscTable
/// </summary>
/// <param name = "_transDate">transdate</param>
/// <returns>PriceDiscTable record</returns>
PriceDiscTable NDX_GetHKActivePriceDisc(TransDate _transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
{
    InventDim           inventDim       = inventDim::find(inventDim::inventDimIdBlank());
    InventTable         inventTable     = this.inventTable();

    KCS_HK2Vendor       hk2Vendor       = inventTable.KCS_HK2Vendor ? inventTable.KCS_HK2Vendor : inventTable.PrimaryVendorId;

    PriceDiscParameters priceDiscParameters;
    PriceDisc           priceDisc;
    PriceDiscTable      avaPriceDiscTable;

    Qty                 qty             = 1;
    PriceGroupId        priceGroupId    = '';

    if (InventItemSetupSupplyType::getDefaultOrderType(inventTable.ItemId, inventTable.DataAreaId) ==  ReqPOType::Purch && hk2Vendor == '')
    {
        return avaPriceDiscTable;
    }

    priceDiscParameters = PriceDiscParameters::construct();

    priceDiscParameters.parmModuleType(ModuleInventPurchSales::Purch);
    priceDiscParameters.parmItemId(this.ItemId);
    priceDiscParameters.parmInventDim(inventDim);
    PriceDiscParameters.parmUnitID(inventTable.purchUnitId());
    PriceDiscParameters.parmPriceDiscDate(_transDate);
    PriceDiscParameters.parmQty(qty);
    PriceDiscParameters.parmAccountNum(hk2Vendor);
    priceDiscParameters.parmCurrencyCode();

    priceDisc = PriceDisc::newFromPriceDiscParameters(priceDiscParameters);
    priceDisc.findPrice(priceGroupId);

    avaPriceDiscTable = priceDisc.priceTable();
    return PriceDiscTable::avaFindActivePriceDiscTable(avaPriceDiscTable, _transDate);
}

/// <summary>
/// Show HK price
/// </summary>
/// <param name = "_transDate">transdate</param>
/// <returns>HK Price</returns>
Price NDX_showHKPriceDisc(TransDate _transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
{
    InventDim           inventDim       = inventDim::find(inventDim::inventDimIdBlank());
    InventTable         inventTable     = this.inventTable();

    KCS_HK2Vendor       hk2Vendor       = inventTable.KCS_HK2Vendor ? inventTable.KCS_HK2Vendor : inventTable.PrimaryVendorId;

    PriceDiscParameters priceDiscParameters;
    PriceDisc           priceDisc;
    PriceDiscTable      avaPriceDiscTable;

    Qty                 qty             = 1;
    PriceGroupId        priceGroupId    = '';

    KCS_PRMPriceSales   priceSales;

    if (InventItemSetupSupplyType::getDefaultOrderType(inventTable.ItemId, inventTable.DataAreaId) ==  ReqPOType::Purch && hk2Vendor == '')
    {
        return 0;
    }

    priceDiscParameters = PriceDiscParameters::construct();

    priceDiscParameters.parmModuleType(ModuleInventPurchSales::Purch);
    priceDiscParameters.parmItemId(this.ItemId);
    priceDiscParameters.parmInventDim(inventDim);
    PriceDiscParameters.parmUnitID(inventTable.purchUnitId());
    PriceDiscParameters.parmPriceDiscDate(_transDate);
    PriceDiscParameters.parmQty(qty);
    PriceDiscParameters.parmAccountNum(hk2Vendor);
    priceDiscParameters.parmCurrencyCode();

    priceDisc = PriceDisc::newFromPriceDiscParameters(priceDiscParameters);
    priceDisc.findPrice(priceGroupId);

    avaPriceDiscTable = priceDisc.priceTable();
    priceSales = avaPriceDiscTable.AVAchargeAmountInventUnit(_transDate) ;
    return priceSales;
}

