/// <summary>
/// Gets simulated Hk2 price
/// </summary>
/// <returns>simulated Hk2 price</returns>
Price NDX_showHK2sim()
{
    InventItemPriceSim  inventItemPriceSim;
    InventParameters    inventParameters    = InventParameters::find();
    KCS_HK2FactorGroup  hK2FactorGroup      = KCS_HK2FactorGroup::findDate(this.InventTable().KCS_HK2GroupId, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    KCS_HK2Factor       hK2Factor           = 1000;
    Price               retPrice;

    inventItemPriceSim  = InventItemPriceSim::KCS_findDate( this.ItemId, this.KCS_showCostingVersionId(),
        DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), this.KCS_showCostingPriceType(), inventDim::inventDimIdBlank(),
        InventLocation::find(inventParameters.FallbackInventLocationId).InventSiteId);

    if(hK2FactorGroup)
    {
        hk2Factor = hK2FactorGroup.HK2Factor * hK2Factor;
    }

    retPrice = inventItemPriceSim.pcsPrice() * hK2Factor;

    return retPrice;
}

