}

public void update(boolean _updatePriceDate, boolean _updatePrice)
{
    InventTableModule inventTableModuleOrig = this.orig();
    next update(_updatePriceDate, _updatePrice);

    if(inventTableModuleOrig.ModuleType == ModuleInventPurchSales::Invent && inventTableModuleOrig.NDXMGKGroupRefRecId != this.NDXMGKGroupRefRecId)
    {
        NDXMGKGroupHistory::createByInventTableModule(this, inventTableModuleOrig);
    }

    if(inventTableModuleOrig.ModuleType == ModuleInventPurchSales::Invent 
        //|| inventTableModuleOrig.ModuleType == ModuleInventPurchSales::Purch)          Maybe later
        && inventTableModuleOrig.Price != this.Price)
    {
        NDXHK1History::createByInventTableModule(this, inventTableModuleOrig);
    }
}
